#!/usr/bin/env bash
set -euo pipefail
ROOT=/workspaces/aegis-sports-command-center
cd "$ROOT"

printf '
== GameTwin v2.1.1 Polish Pass 3 ==
'
printf 'Branch: '; git branch --show-current

mkdir -p /tmp/gametwin-pass3-backup
cp public/gametwin-3d-loader.js /tmp/gametwin-pass3-backup/gametwin-3d-loader.js
cp public/gametwin.html /tmp/gametwin-pass3-backup/gametwin.html

base64 -d > public/gametwin-polish-v2.1.1.mjs <<'B64POLISH'

B64POLISH

base64 -d > public/gametwin-3d-loader.js <<'B64LOADER'

B64LOADER

base64 -d > tests/gametwin-polish-v2.1.1.test.js <<'B64TEST'

B64TEST

python3 - <<'PYHTML'
from pathlib import Path
p=Path('public/gametwin.html')
s=p.read_text()
s=s.replace('AEGIS GameTwin v2.1.0 Deployment-Ready Shadow Lab','AEGIS GameTwin v2.1.1 Polished Shadow Lab')
s=s.replace('GameTwin v2.1.0 Deployment-Ready Shadow Lab','GameTwin v2.1.1 Polished Shadow Lab')
s=s.replace('/gametwin-3d-loader.js?v=2.1.0','/gametwin-3d-loader.js?v=2.1.1')
p.write_text(s.rstrip('\n')+'\n')
PYHTML

printf '
== Syntax / test gate ==
'
node --check public/gametwin-polish-v2.1.1.mjs
node --check public/gametwin-3d-loader.js
node --check tests/gametwin-polish-v2.1.1.test.js
git diff --check
npm run check

printf '
== Changed files ==
'
git status --short
printf '
== Diff stat ==
'
git diff --stat
printf '
PASS 3 READY — no commit or push performed.
'
printf 'Preview with: npm start, then reload /gametwin.html?demo=1
'
